import { ICON_CODEPOINTS } from "@/lib/icon-codepoints";

/**
 * Material Symbols Outlined glyph.
 *
 * The face is subset to the names CarePoint uses and served from public/fonts;
 * `lib/icon-codepoints.ts` is generated by scripts/build_icon_font.py, which
 * fails the build if a name does not exist in the source font. Addressing the
 * glyph by codepoint (rather than by ligature name) is what keeps the subset
 * at a few kilobytes instead of dragging in all 4,000 icons.
 *
 * Every icon is decorative: the surrounding label carries the meaning, and both
 * are announced together, so the glyph itself is hidden from assistive tech.
 */
export default function Icon({
  name,
  size = 30,
  className = "",
}: {
  name: string;
  size?: number;
  className?: string;
}) {
  const codepoint = ICON_CODEPOINTS[name];

  return (
    <span
      aria-hidden="true"
      className={`ms ${className}`.trim()}
      style={{ fontSize: size }}
    >
      {/* A missing name is a build-time failure; this guard only keeps a stale
          map from rendering the literal string "undefined" in production. */}
      {codepoint === undefined ? "?" : String.fromCodePoint(codepoint)}
    </span>
  );
}
